+    // Zero out C first; the harness does not do it for us and we accumulate.
+    std::fill(C, C + (size_t)n * n, 0.0f);
+    constexpr int BM = 64, BK = 64;
+    constexpr int NR = 4;  // NEON vector width in elements
+
+    for (int ii = 0; ii < n; ii += BM) {
+        int imax = std::min(ii + BM, n);
+        for (int kk = 0; kk < n; kk += BK) {
+            int kmax = std::min(kk + BK, n);
+            for (int i = ii; i < imax; ++i) {
+                const float* a_row = A + i * n + kk;
+                float* c_row = C + i * n;
+
+                for (int k = kk; k < kmax; ++k) {
+                    float a_val = a_row[k - kk];
+                    const float* b_row = B + k * n;
+
+                    // Process 4 elements at a time with NEON
+                    for (int j = 0; j + NR <= n; j += NR) {
+                        float32x4_t c_vec = vld1q_f32(c_row + j);
+                        float32x4_t b_vec = vld1q_f32(b_row + j);
+                        float32x4_t a_broadcast = vdupq_n_f32(a_val);
+                        c_vec = vfmaq_f32(c_vec, b_vec, a_broadcast);
+                        vst1q_f32(c_row + j, c_vec);
+                    }
+
+                    // Scalar tail
+                    for (int j = n - (n % NR); j < n; ++j) {
+                        c_row[j] += a_val * b_row[j];
+                    }
+                }
+            }
         }
+    }
 }
